{"command": "cd /workspace && cat > /workspace/efftest.py <<'EOF'
import subprocess, json, numpy as np, wave, os
def run(*a): return subprocess.run(list(a),capture_output=True,text=True)
def call(t,a): return run('ft2','call',t,json.dumps(a))
run('ft2','call','module_new',json.dumps({"name":"eff","channels":2}))
call('sample_load',{"path":"/workspace/samples/sine440_8363.wav","instrument":1,"sample":0})
call('sample_set',{"instrument":1,"sample":0,"volume":64,"relative_note":0,"finetune":0,"loop_start":0,"loop_length":2090,"flags":1})
def rms(fn,t0,t1):
    w=wave.open(fn); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float); w.close()
    s=d[int(t0*44100):int(t1*44100)]
    if len(s)<100: return -1
    return float(np.sqrt((s**2).mean()))
def spec(fn,t0):
    w=wave.open(fn); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float); w.close()
    seg=d[int(t0*44100):int(t0*44100)+8192]
    sp=np.abs(np.fft.rfft(seg*np.hanning(len(seg)),1<<18)); f=np.fft.rfftfreq(1<<18,1/44100)
    m=(f>50)&(f<5000); i=np.argmax(sp[m]); return round(f[m][i],1)
tests=[("none",None,None),("porta_up",1,0x10),("vib",4,0x46),("volslide",10,0x04),("pan",8,0x00),("retrig",0x0E,0x64),("offset",9,0)]
for name,eff,par in tests:
    call('pattern_clear',{"pattern":0})
    kw={"pattern":0,"row":0,"channel":0,"note":"C-6","instrument":1}
    call('pattern_set_cell',kw)
    if eff is not None: call('pattern_set_cell',{"pattern":0,"row":4,"channel":0,"effect":eff,"effect_param":par})
    call('module_render',{"path":"/workspace/eff.wav","rate":44100,"bits":16})
    print(f"{name:10s} rms0.2-0.4={rms('/workspace/eff.wav',0.2,0.4):8.1f} rms0.9-1.0={rms('/workspace/eff.wav',0.9,1.0):8.1f} rms1.4-1.5={rms('/workspace/eff.wav',1.4,1.5):8.1f} freq@0.3={spec('/workspace/eff.wav',0.3)}")
EOF
python3 /workspace/efftest.py"}

