import numpy as np, wave, sys
def load(fn):
    w=wave.open(fn); n=w.getnchannels()
    d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float).reshape(-1,n); w.close()
    return d.mean(axis=1)
def peaks(mono,t0,dur,lo=40,hi=4000,k=18,order=6):
    seg=mono[int(t0*44100):int((t0+dur)*44100)]
    N=1<<int(np.ceil(np.log2(len(seg)))*1)+2
    sp=np.abs(np.fft.rfft(seg*np.hanning(len(seg)),N)); f=np.fft.rfftfreq(N,1/44100)
    m=(f>=lo)&(f<=hi); sm=sp[m]; fm=f[m]
    idx=[i for i in range(order,len(sm)-order) if sm[i]==max(sm[i-order:i+order+1])]
    idx.sort(key=lambda i:-sm[i])
    out=[]
    for i in idx:
        if all(abs(fm[i]-p)>0.03*p for p in out): out.append(fm[i])
        if len(out)>=k: break
    return sorted(round(p,1) for p in out)
if __name__=='__main__':
    mono=load(sys.argv[1])
    t0=float(sys.argv[2]); dur=float(sys.argv[3])
    lo=float(sys.argv[4]) if len(sys.argv)>4 else 40
    hi=float(sys.argv[5]) if len(sys.argv)>5 else 4000
    print(peaks(mono,t0,dur,lo,hi))
