import struct
def inst1(fn):
    b=open(fn,'rb').read()
    p=336
    patterns=struct.unpack('<H',b[70:72])[0]
    for pi in range(patterns):
        hlen=struct.unpack('<I',b[p:p+4])[0]
        rows,psize=struct.unpack('<HH',b[p+5:p+9]); p+=hlen+psize
    instruments=struct.unpack('<H',b[72:74])[0]
    out=[]
    for i in range(instruments):
        ilen=struct.unpack('<I',b[p:p+4])[0]
        hdr=b[p:p+ilen]; p+=ilen
        nsamp=struct.unpack('<H',hdr[27:29])[0]
        if nsamp>0:
            sh=b[p:p+40]
            slen,ls,ll=struct.unpack('<III',sh[0:12]); vol,fine,typ,pan,rel=struct.unpack('<BBBBb',sh[12:17])
            out.append((i+1,hdr[4:26].split(b'\0')[0],slen,ls,ll,vol,fine,typ,pan,rel))
            p+=40
            for _ in range(nsamp):
                sl=struct.unpack('<I',b[p:p+4])[0]; p+=slen
        else:
            out.append((i+1,hdr[4:26].split(b'\0')[0],None,None,None,None,None,None,None,None))
    return out
for f in ['/workspace/A.xm']:
    for row in inst1(f): print(row)
